import type Database from "@tauri-apps/plugin-sql";

/**
 * Applies the SQL migrations generated by drizzle-kit in `drizzle/`.
 * Drizzle's own migrator reads files with `fs`, which doesn't exist in the
 * webview, so the files are bundled by Vite and tracked in `__migrations`.
 */
const files = import.meta.glob<string>("../../drizzle/*.sql", {
  query: "?raw",
  import: "default",
  eager: true,
});

const migrations = Object.entries(files)
  .map(([path, sql]) => ({
    tag: path
      .split("/")
      .pop()!
      .replace(/\.sql$/, ""),
    sql,
  }))
  .sort((a, b) => a.tag.localeCompare(b.tag));

export async function runMigrations(sqlite: Database) {
  await sqlite.execute(
    "CREATE TABLE IF NOT EXISTS __migrations (tag TEXT PRIMARY KEY, applied_at INTEGER NOT NULL)",
  );
  const applied = new Set(
    (
      await sqlite.select<{ tag: string }[]>("SELECT tag FROM __migrations")
    ).map((row) => row.tag),
  );

  for (const { tag, sql } of migrations) {
    if (applied.has(tag)) continue;
    const statements = sql
      .split("--> statement-breakpoint")
      .map((s) => s.trim())
      .filter(Boolean);
    for (const statement of statements) {
      await sqlite.execute(statement);
    }
    await sqlite.execute(
      "INSERT INTO __migrations (tag, applied_at) VALUES ($1, $2)",
      [tag, Date.now()],
    );
  }
}
